 synchronized boolean switchTorrent(String id)throws Exception{JSONObject job=job(id);if(job==null||job.optInt("torrentSwitches")>=2)return false;JSONObject previous=choice(job);JSONArray tried=previous.optJSONArray("tried");if(tried==null)tried=new JSONArray();tried.put(sourceIdentity(previous));Set<String> seen=new HashSet<>();for(int n=0;n<tried.length();n++)seen.add(tried.optString(n));for(JSONObject c:DataStore.objects(previous.optJSONArray("alternatives")))if((c.optString("service").equals("torrent")||c.optString("service").equals("direct"))&&!seen.contains(sourceIdentity(c))){JSONObject next=DataStore.copy(c);DataStore.put(next,"alternatives",previous.optJSONArray("alternatives"));DataStore.put(next,"tried",tried);source(id,next);file(id,true).delete();for(JSONObject j:DataStore.objects(jobs))if(j.optString("id").equals(id)){DataStore.put(j,"kind",next.optString("service").equals("torrent")?"torrent":"http");DataStore.put(j,"hash",next.optString("hash"));DataStore.put(j,"fileIdx",next.optInt("fileIdx",-1));DataStore.put(j,"torrentSwitches",job.optInt("torrentSwitches")+1);DataStore.put(j,"switchMessage",PhoneTorrent.SWITCHED);update(id,"queued",0,next.optLong("size"),"","");return true;}}return false;}
 static String sourceIdentity(JSONObject c){return c.optString("service")+":"+c.optString("hash")+":"+c.optInt("fileIdx",-1)+":"+c.optString("url");}
 void deleteTorrentData(){torrents.stopAll();for(JSONObject j:DataStore.objects(jobs()))if(torrents.isTorrent(j))torrents.stop(j.optString("id"),true);for(File dir:storageDirectories())PhoneTorrent.erase(new File(dir,".torrents"));PhoneTorrent.erase(new File(context.getFilesDir(),"torrent-engine"));}
