 DownloadStore(Context c){this(c,PhoneDownloadProvider::new);}
 DownloadStore(Context c,java.util.function.Function<JSONObject,PhoneDownloadProvider> providers){DownloadHubActivity.words();this.providers=providers;context=c.getApplicationContext();File base=c.getExternalFilesDir(null);directory=new File(base==null?c.getFilesDir():base,"offline");directory.mkdirs();AtomicFile queue=new AtomicFile(new File(c.getFilesDir(),"downloads.json"));boolean changed=false;try{jobs=new JSONArray(new String(queue.readFully(),java.nio.charset.StandardCharsets.UTF_8));}catch(FileNotFoundException e){jobs=new JSONArray();if(queue.getBaseFile().exists()||new File(queue.getBaseFile()+".bak").exists())queueFailure=QUEUE_ERROR;}catch(Exception e){jobs=new JSONArray();queueFailure=QUEUE_ERROR;}if(!queueFailure.isEmpty()){try{File source=queue.getBaseFile();if(source.isFile())java.nio.file.Files.copy(source.toPath(),new File(c.getFilesDir(),"downloads-unreadable-"+System.currentTimeMillis()+".json").toPath());}catch(Exception ignored){}}else{for(JSONObject job:DataStore.objects(jobs))if(job.optString("status").equals("downloading")){DataStore.put(job,"status","paused");changed=true;}if(changed)save();}if(PhoneReady.at(context.getFilesDir()).enabled())PhoneReadyJob.refill(context);PhonePickupJob.schedule(context);}
